import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"08｜工程初始化（上）：后端骨架与公共基础设施","description":"","frontmatter":{},"headers":[{"level":2,"title":"先想清楚怎么拆","slug":"先想清楚怎么拆","link":"#先想清楚怎么拆","children":[]},{"level":2,"title":"分步搭建","slug":"分步搭建","link":"#分步搭建","children":[{"level":3,"title":"第一步：Maven多模块骨架","slug":"第一步-maven多模块骨架","link":"#第一步-maven多模块骨架","children":[]},{"level":3,"title":"第二步：hify-common 公共基础设施","slug":"第二步-hify-common-公共基础设施","link":"#第二步-hify-common-公共基础设施","children":[]},{"level":3,"title":"第三步：业务模块空壳","slug":"第三步-业务模块空壳","link":"#第三步-业务模块空壳","children":[]},{"level":3,"title":"第四步：验收","slug":"第四步-验收","link":"#第四步-验收","children":[]}]},{"level":2,"title":"大批量代码怎么 review","slug":"大批量代码怎么-review","link":"#大批量代码怎么-review","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级全链路开发实战/08｜工程初始化（上）：后端骨架与公共基础设施.md","filePath":"ClaudeCode企业级全链路开发实战/08｜工程初始化（上）：后端骨架与公共基础设施.md","lastUpdated":1779815375000}'),n={name:"ClaudeCode企业级全链路开发实战/08｜工程初始化（上）：后端骨架与公共基础设施.md"};function E(o,e,l,p,c,r){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="_08-工程初始化-上-后端骨架与公共基础设施" tabindex="-1">08｜工程初始化（上）：后端骨架与公共基础设施 <a class="header-anchor" href="#_08-工程初始化-上-后端骨架与公共基础设施" aria-label="Permalink to &quot;08｜工程初始化（上）：后端骨架与公共基础设施&quot;">​</a></h1><p>你好，我是Robert。</p><p>从这节课开始，我们正式进入工程部分。先来展示下Hify的本地工作界面吧，让你知道我们即将完成的软件系统是什么样子的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/65f07dd405797cb17e305c5a7baf4cdc.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/65f07dd405797cb17e305c5a7baf4cdc.png" alt=""></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/7f8f4f03d6639766e8575002e7047006.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/7f8f4f03d6639766e8575002e7047006.png" alt=""></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/7496471b6917d24f75fd5bb2a34e31a0.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/7496471b6917d24f75fd5bb2a34e31a0.png" alt=""></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/761c2bb967ac7c33e3513206a60e1b53.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/761c2bb967ac7c33e3513206a60e1b53.png" alt=""></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/c529e54f99a827781ceb099d7cf5c138.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/c529e54f99a827781ceb099d7cf5c138.png" alt=""></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/11aac74261e6656f2cc8a41fe14602f7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/11aac74261e6656f2cc8a41fe14602f7.png" alt=""></a></p><p>好，看完了效果，我们开始今天的课程内容。先回顾一下，04讲我们定了模块化单体、Maven 9个模块的应用架构，05讲定了单机部署、线程池隔离、熔断策略的运行架构，06讲把这一切写进了CLAUDE.md。蓝图画完了，现在按图施工。</p><p>这一讲要做的事： <strong>让 Claude Code 搭建 Hify 后端的工程骨架</strong>。Maven多模块结构、公共基础设施（统一响应、全局异常处理、MyBatis-Plus配置、Redis配置）、业务模块的空壳，全部就位。搭完之后， <code>java -jar</code> 能跑起来，访问健康检查接口返回200。</p><p>前端工程和启动脚本放到下一讲。这一讲先把后端的地基打扎实。</p><h2 id="先想清楚怎么拆" tabindex="-1">先想清楚怎么拆 <a class="header-anchor" href="#先想清楚怎么拆" aria-label="Permalink to &quot;先想清楚怎么拆&quot;">​</a></h2><p>你可能会想：工程初始化不就是模板性工作吗？把CLAUDE.md喂给Claude Code，说一句“帮我初始化Hify后端项目”不就完了？</p><p>我试过，效果不好。</p><p>Claude Code一次性生成了几十个文件，看起来很完整。但仔细一看：父pom里的模块声明和实际目录不一致，hify-common的依赖被写进了hify-chat的pom里，MyBatis-Plus的版本和Spring Boot的版本有冲突，全局异常处理器和Result类用了两种不同的错误码格式。</p><p>问题不在Claude Code能力不够，是一次性生成的东西太多了，它没法保证所有细节都自洽。几十个文件之间有大量的依赖和关联，一个地方错了会连锁影响其他地方。而且生成量太大，你review起来也吃力，容易漏掉问题。</p><p>当然随着模型能力越来越强，这个问题也会慢慢解决甚至不存在。但是即使有那一天，我也是希望你能把后面的内容看完。 <strong>因为我们要做的是一个可持续迭代的系统，而不是挑战 Claude Code 的能力</strong>。我希望你学到是“道”而不只是“术”。</p><p>所以第一个方法论在这里出场： <strong>面对体量大的任务，要拆</strong>。</p><p>怎么判断该不该拆？两个标准：</p><ol><li><p>标准一：生成的代码量是否超出你一次能review的范围。十几行代码，肉眼扫一遍就行，不用拆。几十个文件、几百行配置，一次看不过来，必须拆。</p></li><li><p>标准二：步骤之间是否有依赖关系。如果第二步依赖第一步的结果（比如业务模块的pom依赖公共模块的pom），那就应该先完成第一步、验证正确，再做第二步。否则第一步错了，第二步会错得更离谱。</p></li></ol><p>工程初始化两个条件都满足。所以我把它拆成四步：</p><ol><li>Maven多模块骨架（父pom + 子模块pom + 目录结构）</li><li>hify-common公共基础设施（Result、BizException、全局异常处理、配置类）</li><li>业务模块空壳（每个模块的package结构和启动验证）</li><li>验收，启动项目，确认一切正常</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/465a508ec31f34c9c6558e0258918e9d.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/465a508ec31f34c9c6558e0258918e9d.jpg" alt=""></a></p><p>为什么是这个顺序？依赖关系决定了顺序。Maven骨架是所有东西的容器，必须先有。hify-common被所有业务模块依赖，排第二。业务模块依赖common，排第三。最后验收确认整体能跑。</p><p><strong>先地基，后框架，最后验收。这个顺序不只适用于工程初始化，后面做任何模块都是这个思路</strong>。</p><h2 id="分步搭建" tabindex="-1">分步搭建 <a class="header-anchor" href="#分步搭建" aria-label="Permalink to &quot;分步搭建&quot;">​</a></h2><h3 id="第一步-maven多模块骨架" tabindex="-1">第一步：Maven多模块骨架 <a class="header-anchor" href="#第一步-maven多模块骨架" aria-label="Permalink to &quot;第一步：Maven多模块骨架&quot;">​</a></h3><p>目标很明确：创建父pom和所有子模块的pom，把目录结构搭出来，依赖关系配对。</p><p>给Claude Code的指令思路：</p><blockquote><p>按照CLAUDE.md中的项目结构和技术栈，创建Hify的Maven多模块工程骨架。父pom声明所有子模块，统一管理Spring Boot、MyBatis-Plus、Redis等版本号。子模块之间的依赖关系按CLAUDE.md中定义的架构来。只创建pom和目录结构，不需要写Java代码。</p></blockquote><p>注意最后一句，“只创建pom和目录结构，不需要写Java代码”。这是控制范围的关键。不说这句，Claude Code会顺手给你生成Application类、配置文件、甚至示例代码，和后面步骤冲突。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/9e37d3d49b58130af046f02b1208fb6e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/9e37d3d49b58130af046f02b1208fb6e.png" alt=""></a></p><p>拿到输出后，重点检查三件事：</p><ol><li><p>模块声明和目录结构是否一致。父pom里声明的 <code>&amp;lt;modules&gt;</code> 列表和实际创建的目录要完全对应，一个不多一个不少。</p></li><li><p>依赖关系是否正确。hify-chat的pom里应该有对hify-agent和hify-provider的依赖，hify-agent的pom里应该有对hify-mcp的依赖。交叉检查，不要有多余的依赖，也不要有遗漏。</p></li><li><p>版本管理是否统一。Spring Boot、MyBatis-Plus、Redis的版本号应该只出现在父pom的 <code>&amp;lt;dependencyManagement&gt;</code> 里，子模块不重复声明版本。</p></li></ol><p>这些都没问题，第一步完成。有问题让Claude Code改，不要手动改，让它按规范输出。</p><h3 id="第二步-hify-common-公共基础设施" tabindex="-1">第二步：hify-common 公共基础设施 <a class="header-anchor" href="#第二步-hify-common-公共基础设施" aria-label="Permalink to &quot;第二步：hify-common 公共基础设施&quot;">​</a></h3><p>这一步是重中之重。hify-common里的东西会被所有业务模块依赖——Result类、异常处理、MyBatis-Plus配置。这里出了问题，后面每个模块都会跟着错。</p><p>我把这一步进一步拆成五个小任务。前三个有依赖链（异常处理器依赖Result和BizException），后两个相对独立。顺序还是按依赖关系排。</p><p><strong>任务一：统一响应 Result 和分页 PageResult</strong></p><p>Cluade 的指令是：</p><blockquote><p>在hify-common中创建统一响应类。按照CLAUDE.md接口规范：Result&lt;T&gt; 包含 code、message、data三个字段，提供ok()和fail()静态方法。PageResult&lt;T&gt;继承Result，额外包含total、page、size。</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/9d6dfea3e370e0ee5156441e1b1e37aa.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/9d6dfea3e370e0ee5156441e1b1e37aa.png" alt=""></a></p><p>这个任务简单、边界清晰，Claude Code基本不会出错。</p><p><strong>任务二：错误码枚举和业务异常</strong></p><p>Cluade的指令是：</p><blockquote><p>在hify-common中创建错误码枚举ErrorCode和业务异常类BizException。ErrorCode包含code和message，覆盖通用错误（参数错误、未授权、系统内部错误等）。BizException持有ErrorCode，支持自定义message覆盖。</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/fda0902fa6c21f3bc77ce1ec596cf852.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/fda0902fa6c21f3bc77ce1ec596cf852.png" alt=""></a></p><p><strong>任务三：全局异常处理器</strong></p><p>Cluade 的指令是：</p><blockquote><p>在hify-common中创建全局异常处理器GlobalExceptionHandler，使用@RestControllerAdvice。捕获BizException返回对应错误码，捕获MethodArgumentNotValidException返回参数校验错误，兜底捕获Exception返回系统内部错误。所有异常响应必须使用Result.fail()和ErrorCode枚举。</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/81617cf086f0eaff3e1efc8530279da9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/81617cf086f0eaff3e1efc8530279da9.png" alt=""></a></p><p>这个任务值得多说一点。我第一次让Claude Code生成这个处理器的时候，它在兜底的Exception处理里硬编码了 <code>code: 500, message: &quot;系统繁忙&quot;</code>，没有用ErrorCode枚举。功能上没问题，但违反了CLAUDE.md里定义的规范——所有错误响应必须走ErrorCode。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/a3b5c6yybf86675a9a9b6yy2daafa527.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/a3b5c6yybf86675a9a9b6yy2daafa527.png" alt=""></a></p><p>这就是 SDD 闭环在起作用的时刻。我让它改成 <code>Result.fail(ErrorCode.INTERNAL_ERROR)</code>，然后在CLAUDE.md的行为指令里补了一条：“异常处理必须使用ErrorCode枚举，禁止硬编码错误码和错误信息。” 下次再让它写类似代码，这个问题就不会重复出现。</p><p><strong>每次 AI 跑偏，不只是改掉当前的错，更要把规范补上，堵住同类问题的口子</strong>。这就是SDD闭环的日常运转——定规范、AI执行、发现偏差、迭代规范。不是什么宏大的流程，就是写代码过程中随手做的事。</p><p><strong>任务四：MyBatis-Plus 配置</strong></p><p>Cluade 的指令是：</p><blockquote><p>在hify-common中创建MyBatis-Plus配置类。包含：分页插件、自动填充（createTime、updateTime）、逻辑删除配置。</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/93dbf3d01fc0d361c1cd632a57029581.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/93dbf3d01fc0d361c1cd632a57029581.png" alt=""></a></p><p>这里只做配置层面的基础搭建。具体的业务封装——BaseEntity基类、分页查询工具类——在基础组件篇展开。这里想说一下，Claude生成这种模板代码非常快，基本不会出错，因为这些代码是非常标准的。</p><p><strong>任务五：Redis 配置</strong></p><p>Cluade的指令是：</p><blockquote><p>在hify-common中创建Redis配置类。包含：RedisTemplate序列化配置（key用String，value用JSON）、基础的RedisUtil工具类（get/set/delete/expire）。</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/796ff53815b61c2ecc2c15fc4bcabd53.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/796ff53815b61c2ecc2c15fc4bcabd53.png" alt=""></a></p><p>同样，这里只做配置。Cache-Aside模式的业务封装在基础组件篇再做。</p><p>你可能注意到了，我把hify-common拆成了五个小任务，而不是一条指令“帮我把hify-common全部搭好”。原因和前面讲的一样：拆开做， <strong>每个任务的上下文更小、更聚焦，Claude Code的输出质量更高。</strong> 而且出了问题容易定位，混在一起生成，一个地方有问题可能要在几百行代码里找。</p><h3 id="第三步-业务模块空壳" tabindex="-1">第三步：业务模块空壳 <a class="header-anchor" href="#第三步-业务模块空壳" aria-label="Permalink to &quot;第三步：业务模块空壳&quot;">​</a></h3><p>前两步搞定后，后端的地基就打好了。现在给每个业务模块创建基础的package结构。</p><blockquote><p>为hify-provider、hify-agent、hify-chat、hify-mcp等业务模块创建标准的package结构。按照CLAUDE.md代码组织规范，每个模块包含controller/service/service-impl/mapper/entity/dto/config目录。每个模块只创建package和一个空的占位类，不需要写业务代码。</p></blockquote><p>这一步生成的东西很简单，review也快——检查package路径对不对、各模块结构是否一致就行。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/c4b819952c860118e5ed6baf12c08e9a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/c4b819952c860118e5ed6baf12c08e9a.png" alt=""></a></p><p>然后在hify-app模块里创建Spring Boot启动类和application.yml：</p><blockquote><p>在hify-app中创建Spring Boot启动类HifyApplication，以及application.yml配置文件。配置项包括：数据库连接、Redis连接、MyBatis-Plus配置、服务端口8080。</p></blockquote><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/acdaa9bbee0993713fc0c30ac44e6f4c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/acdaa9bbee0993713fc0c30ac44e6f4c.png" alt=""></a></p><h3 id="第四步-验收" tabindex="-1">第四步：验收 <a class="header-anchor" href="#第四步-验收" aria-label="Permalink to &quot;第四步：验收&quot;">​</a></h3><p>后端骨架应该搭好了。启动验证一下。</p><p>先确保MySQL和Redis在本地跑着（如果本地没有，用Docker临时起一个，这不是项目的Docker化，只是本地开发环境）。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hify</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DskipTests</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hify-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spring-boot:run</span></span></code></pre></div><p>然后，我mvn clean install就报错了：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/235aaef6b14c40e012e6b701b3063682.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/235aaef6b14c40e012e6b701b3063682.png" alt=""></a></p><p>然后我继续输入：</p><blockquote><p>mvn clean install -DskipTests 失败了，修复下</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/c54f4c5ca1788577cbcd52ff22abbayy.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/c54f4c5ca1788577cbcd52ff22abbayy.png" alt=""></a></p><p>然后修复这个问题又失败了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/ea9000c302d1a3dac0488ecb9769109c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/ea9000c302d1a3dac0488ecb9769109c.png" alt=""></a></p><p>那就继续让Claude Code继续修复。这个过程重复，就可以得到一个可以启动的应用了。</p><p>这里一直起不来，后来Claude Code发现前面给的启动命令错了（哈哈），应该是下面这个命令：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mvn spring-boot:run -pl hify-app</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/34b077f38a9dc0df6750cbce1ffe464e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/34b077f38a9dc0df6750cbce1ffe464e.png" alt=""></a></p><p>Spring Boot启动日志的最后一行应该显示 <code>Started HifyApplication in X seconds</code>。</p><p>为了有一个可验证的端点，让Claude Code加一个健康检查接口：</p><p>在hify-app中创建HealthController，路径 GET /api/v1/health，返回 Result.ok(“Hify is running”)。</p><p>启动后访问 <code>http://localhost:8080/api/v1/health</code>，应该可以看到：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hify is running&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>看到这个返回，说明后端骨架搭建成功。Maven多模块结构正常、依赖关系正确、公共模块的Result和全局异常处理在工作、Spring Boot配置没问题。</p><p>但是输出却是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/a6dbdf324c7b45f181778f5761777693.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/a6dbdf324c7b45f181778f5761777693.png" alt=""></a></p><p>接下来就交给你了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/0e33d73c6f849b74feffae8aaf05d69e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/0e33d73c6f849b74feffae8aaf05d69e.png" alt=""></a></p><h2 id="大批量代码怎么-review" tabindex="-1">大批量代码怎么 review <a class="header-anchor" href="#大批量代码怎么-review" aria-label="Permalink to &quot;大批量代码怎么 review&quot;">​</a></h2><p>这一讲Claude Code生成了不少代码，几十个文件、几百行配置和基础代码。逐行看不现实，也没必要。关键是按优先级看。</p><ol><li><p>第一优先级：结构性问题。模块依赖关系对不对？pom里的依赖声明和CLAUDE.md里定义的架构一致吗？package路径对不对？这些如果错了，后面所有东西都建在错误的地基上。</p></li><li><p>第二优先级：公共模块的核心代码。Result类的字段和方法对不对？全局异常处理器的捕获优先级对不对？MyBatis-Plus的自动填充逻辑对不对？这些代码所有业务模块都会依赖，错了影响范围最大。</p></li><li><p>第三优先级：配置文件。application.yml里的配置项对不对？有没有遗漏？有没有硬编码不该硬编码的东西？影响范围相对小，后面随时可以调整。</p></li><li><p>最后才看：业务模块空壳。只是package结构和占位类，几乎没什么可出错的，扫一眼确认结构一致就行。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/2274e8ae11ea0f756db1ea25598208e2.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/965651/2274e8ae11ea0f756db1ea25598208e2.jpg" alt=""></a></p><p>这个优先级背后的逻辑很简单： <strong>影响范围越大的问题越先查</strong>。结构错了全盘皆输，公共模块错了所有业务模块跟着错，配置错了这个服务有问题，空壳错了只影响一个文件。把review时间花在影响范围最大的地方。</p><p>这个思路不只适用于工程初始化。后面每一讲Claude Code生成大量代码时，都可以用同样的方式。先找影响范围最大的问题，再逐步往下。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这一讲做了两件事：用Claude Code搭建了Hify的后端骨架，以及总结了3个后面会反复使用的方法论。</p><p><strong>任务拆解标准</strong>。生成量是否超出一次review的范围？步骤之间是否有依赖关系？满足其一就拆。拆的顺序按依赖关系来，先地基后框架。</p><p><strong>影响范围 review</strong>。大批量代码不需要逐行看。按影响范围排优先级——结构 &gt; 公共模块 &gt; 配置 &gt; 空壳，时间花在影响范围最大的地方。</p><p><strong>每步验收</strong>。不是搭完全部才验收，而是每一步做完就验证。Maven骨架搭好了 <code>mvn install</code> 能通过吗？公共模块写好了编译没问题吗？全部搭完 <code>spring-boot:run</code> 能启动吗？每一步的验收给你信心：“到这里为止是对的。”不验证就往前冲，错误会累积，到最后都不知道问题出在哪一步。</p><p>到了这里我们依然 <strong>0 代码</strong>，就完成了一个Web Service的初始化。中间基本没遇到问题，很顺。一方面有模型厉害的原因，一方面是我们前面基础搭建的好，一方面是我们把一个大任务拆解为多个小任务了。在后面的课程，你会越来越感受到这个模式的优势。</p><p>你可以思考下，如果我们自己来做这些事情，是不是至少要一天。而有了AI辅助后，可以又快又好的实现。节省下来的时间，就可以用来做其他事情，这就是生产力的提升。</p><p>后端能跑了。下一讲补前端Vue工程、写启动脚本，让Hify的前后端一键跑起来。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>回想一下你之前做项目时的工程初始化过程。你是手动一个个文件创建，用脚手架工具，还是从别的项目复制？如果现在让你用Claude Code来做，你会怎么拆解？试着列出你的步骤和每步的验收标准。</p><p>期待你与我分享自己的使用体验。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,118)])])}const d=t(n,[["render",E]]);export{g as __pageData,d as default};
